"""
    Strips a string right (end) of string if found.  Otherwise, returns the original string.

    :param s: str
    :param pattern: str
    :rtype: str
    """
def strip_right(s: Any, pattern: Any) -> object {
    if s.endswith(pattern) {
        return s[:-len(pattern)];
    } else {
        return s;
    }
}

